<?php
session_start();require __DIR__.'/portal_lib.php';
$clients=ep_read('clientes');$error='';
if(isset($_GET['sair'])){unset($_SESSION['ep_client']);header('Location: portal_cliente.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login'){ep_check();foreach($clients as $c){if(!empty($c['active']) && hash_equals(mb_strtolower((string)$c['user']),mb_strtolower(trim((string)($_POST['user']??'')))) && password_verify((string)($_POST['password']??''),(string)($c['password']??''))){session_regenerate_id(true);$_SESSION['ep_client']=$c['id'];header('Location: index.php');exit;}}$error='Usuário ou senha inválidos.';}
$client=null;foreach($clients as $c)if(($c['id']??'')===($_SESSION['ep_client']??'') && !empty($c['active'])){$client=$c;break;}
if(!$client)unset($_SESSION['ep_client']);
$products=ep_read('products');$quotes=ep_read('orcamentos');
if($client && $_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='send'){
 ep_check();$items=[];$qtys=$_POST['qty']??[];if(!is_array($qtys))$qtys=[];
 foreach($products as $p){$code=(string)($p['code']??'');$qty=max(0,min(999,(int)($qtys[$code]??0)));if($qty<1||!is_numeric($p['price']??null)||$p['price']<0)continue;$items[]=['code'=>$code,'name'=>(string)($p['name']??''),'qty'=>$qty,'price'=>round((float)$p['price'],2),'discount'=>0];if(count($items)>=100)break;}
 if(!$items)$error='Selecione pelo menos um produto que tenha preço cadastrado.';
 else{$now=date('c');$id='cli_'.bin2hex(random_bytes(10));$quotes[]=['id'=>$id,'number'=>'CLI-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)),'user'=>$client['user'],'client_id'=>$client['id'],'customer'=>['name'=>$client['name'],'document'=>$client['document']??'','phone'=>$client['phone']??'','email'=>$client['email']??''],'items'=>$items,'discount'=>0,'status'=>'aguardando_analise','created_at'=>$now,'updated_at'=>$now,'history'=>[['at'=>$now,'user'=>$client['user'],'event'=>'submitted']]];if(ep_write('orcamentos',$quotes)){header('Location: portal_cliente.php?enviado=1');exit;}$error='Falha ao salvar o orçamento.';}
}
if(!$client){?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portal de Clientes — ELEDS Linha Leve e Pesada</title><link rel="stylesheet" href="assets/css/style.css?v=20261002-layoutfix1"></head><body class="admin-body"><div class="admin-login"><div class="admin-logo"><img src="assets/eleds-logo.png" alt="ELEDS Linha Leve e Pesada"><span>Portal de clientes</span></div><h1>Portal de clientes</h1><p>Entre para montar e enviar seu orçamento.</p><?php if($error):?><div class="admin-alert error"><?=ep_h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="login"><label>Usuário<input name="user" autocomplete="username" required></label><label>Senha<input type="password" name="password" autocomplete="current-password" required></label><button class="admin-primary" type="submit">Entrar no portal</button></form><a class="back-link" href="index.php">← Voltar ao catálogo</a></div></body></html><?php exit;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portal de Clientes ELEDS</title><?php ep_style();?></head><body><header><div class="row"><strong>ELEDS — Portal de Clientes</strong><nav><a href="index.php">Catálogo público</a><?php if($client):?><a href="portal_cliente.php?sair=1">Sair</a><?php endif;?></nav></div></header><main><?php if(!$client):?><div class="panel" style="max-width:420px;margin:55px auto"><h2>Entrar</h2><p class="muted">Acesso exclusivo a clientes cadastrados.</p><?php if($error):?><p class="error"><?=ep_h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="login"><p><input name="user" placeholder="Usuário" required autocomplete="username" style="width:95%"></p><p><input type="password" name="password" placeholder="Senha" required autocomplete="current-password" style="width:95%"></p><button>Entrar</button></form></div><?php else:?><h1>Olá, <?=ep_h($client['name'])?></h1><p><a href="index.php">← Voltar ao catálogo com preços</a></p><?php if(isset($_GET['enviado'])):?><p class="ok">Orçamento enviado para análise! Aguarde a liberação da administração.</p><?php endif;?><?php if($error):?><p class="error"><?=ep_h($error)?></p><?php endif;?><div class="panel"><h2>Montar orçamento</h2><p class="muted">Selecione as quantidades. O preço final poderá ser ajustado e liberado pela administração.</p><input id="search" placeholder="Buscar código ou produto" style="width:95%" oninput="document.querySelectorAll('[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(this.value.toLowerCase()))"><form method="post"><input type="hidden" name="csrf" value="<?=ep_csrf()?>"><input type="hidden" name="action" value="send"><div style="overflow-x:auto"><table><thead><tr><th>Produto</th><th>Preço unitário</th><th>Quantidade</th></tr></thead><tbody><?php foreach($products as $p):if(!is_numeric($p['price']??null)||$p['price']<0)continue;$code=(string)($p['code']??'');?><tr data-search="<?=ep_h(mb_strtolower($code.' '.($p['name']??'')))?>"><td><strong><?=ep_h($code)?></strong><br><?=ep_h($p['name']??'')?></td><td><?=ep_money($p['price'])?></td><td><input type="number" min="0" max="999" value="0" data-client-code="<?=ep_h($code)?>" name="qty[<?=ep_h($code)?>]" style="width:85px"></td></tr><?php endforeach;?></tbody></table></div><p><button onclick="return confirm('Enviar este orçamento para análise?')">Enviar para análise</button></p></form></div><div class="panel"><h2>Meus orçamentos</h2><table><tr><th>Número</th><th>Data</th><th>Status</th><th>Valor</th><th>Detalhes</th></tr><?php foreach(array_reverse($quotes) as $q):if(($q['client_id']??null)!==$client['id'])continue;$released=($q['status']??'')==='proposta_enviada';?><tr><td><?=ep_h($q['number']??'')?></td><td><?=ep_h(substr($q['created_at']??'',0,10))?></td><td><?= $released?'Proposta liberada':(($q['status']??'')==='cancelado'?'Cancelado':'Aguardando análise')?></td><td><?= $released?ep_money(ep_total($q)):'Em análise'?></td><td><?php if($released):?><a href="proposta_cliente.php?id=<?=urlencode($q['id'])?>" target="_blank">Ver proposta / imprimir PDF</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table></div><?php endif;?></main><?php if($client): ?><script>
const cartKey='eleds_cart_<?=ep_h(preg_replace('/[^a-zA-Z0-9_-]/','',(string)$client['id']))?>';
try{const cart=JSON.parse(localStorage.getItem(cartKey)||'{}');document.querySelectorAll('[data-client-code]').forEach(input=>{const qty=Number(cart[input.dataset.clientCode]||0);if(qty>0)input.value=Math.min(999,qty);});}catch(e){}
<?php if(isset($_GET['enviado'])): ?>localStorage.removeItem(cartKey);<?php endif; ?>
</script><?php endif; ?></body></html>
